"""Audit untrained observable contrast scores vs known-model errors; not confidence calibration."""
from datetime import datetime,timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,sha256,git


def ranks(values):
    values=np.asarray(values,dtype=float)
    if values.ndim!=1 or not np.isfinite(values).all():raise ValueError('Finite score vector required')
    order=np.argsort(values,kind='stable');result=np.empty(len(values),dtype=float);i=0
    while i<len(order):
        j=i+1
        while j<len(order) and values[order[j]]==values[order[i]]:j+=1
        result[order[i:j]]=(i+j-1)/2;i=j
    return result


def correlation(x,y):
    x,y=ranks(x),ranks(y)
    if len(x)!=len(y) or len(x)<3:raise ValueError('At least3 paired scores required')
    if np.std(x)==0 or np.std(y)==0:return None
    return float(np.corrcoef(x,y)[0,1])


def observables(prediction):
    weights=np.array(prediction['grid_weights']);loss=np.array(prediction['grid_losses'])
    if weights.shape!=(129,) or loss.shape!=(129,) or not np.isfinite(loss).all() or np.any(np.diff(weights)<=0):
        raise ValueError('Finite ordered129 grid required')
    best=int(np.argmin(loss));curvature=None
    if 0<best<128:
        h=weights[best+1]-weights[best]
        curvature=float((loss[best-1]-2*loss[best]+loss[best+1])/(h*h))
    return dict(minimum_loss=float(prediction['loss']),negative_grid_span=-float(loss.max()-loss.min()),
        negative_local_curvature=-curvature if curvature is not None else None,
        grid_minimum_at_boundary=best in (0,128))


def summarize(rows):
    result={}
    for score in ('minimum_loss','negative_grid_span','negative_local_curvature'):
        valid=[r for r in rows if r['scores'][score] is not None]
        result[score]=dict(count=len(valid),omitted=len(rows)-len(valid),rank_correlations={
            error:correlation([r['scores'][score] for r in valid],[r['errors'][error] for r in valid]) if len(valid)>=3 else None
            for error in ('normalized_covariance','physical_covariance','total_hh_log_error')})
    return result


def run():
    started=datetime.now(timezone.utc);folder=ROOT/'docs/validation/raw'
    paths=[folder/n for n in ('sensibilite-poids-amplitude-bruit-v001-20261027T203749Z.json',
        'impact-poids-profils-bruit-v001-20261027T204337Z.json')]
    hashes=[sha256(p) for p in paths];sensitivity,impact=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    records=[]
    for row in sensitivity['records']:
        audit=next(r for r in impact['records'] if r['dataset']==row['dataset'] and r['a']==row['a'] and r['rect']==row['rect'])
        for replicate in row['replicates']:
            actual=next(r for r in audit['replicates'] if r['replicate']==replicate['replicate'])
            pairs=[('baseline',replicate['baseline'],actual['baseline'])]+[(name,trial['prediction'],actual['trials'][name]) for name,trial in replicate['trials'].items()]
            for name,prediction,truth in pairs:
                ratios=np.asarray(truth['hh_total_standard_deviation_ratio'])
                if not np.isfinite(ratios).all() or ratios.min()<=0:raise ValueError('Invalid truth ratios')
                records.append(dict(dataset=row['dataset'],iso=row['iso'],a=row['a'],rect=row['rect'],replicate=replicate['replicate'],scenario=name,
                    scores=observables(prediction),errors=dict(normalized_covariance=truth['shape_metrics']['normalized_covariance_squared_error'],
                        physical_covariance=truth['physical_covariance_squared_error'],total_hh_log_error=float(np.mean(abs(np.log(ratios)))))))
    if len(records)!=616 or [sha256(p) for p in paths]!=hashes:raise ValueError('Incomplete or changed score audit')
    summaries=dict(all=summarize(records),baseline=summarize([r for r in records if r['scenario']=='baseline']),
        by_capture={name:dict(all=summarize([r for r in records if r['a']==name]),baseline=summarize([r for r in records if r['a']==name and r['scenario']=='baseline'])) for name in dict.fromkeys(r['a'] for r in records)})
    now=datetime.now(timezone.utc);output=folder/f'indicateurs-observables-fiabilite-bruit-v001-{now.strftime("%Y%m%dT%H%M%SZ")}.json'
    result=dict(schema_version=1,data_version=1,started_at_utc=started.isoformat(),completed_at_utc=now.isoformat(),records=records,summaries=summaries,
        parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],runner_sha256=sha256(Path(__file__)),runner_source=Path(__file__).read_text(encoding='utf-8'),
        numpy_version=np.__version__,commit=git('rev-parse','HEAD'),verdict='observable_score_feasibility_not_calibrated_confidence',
        rules='No refit/draw/training/threshold. Observableminloss,negativegridspan,negativecenteredcurvature129grid;boundarycurvatureexplicitlymissing. ExacttieaveragerankSpearman vs3knowntrutherrors. Reportall616and56baselines,eachcapture,nostatisticalpvalues.',
        limitations='Amplitudeinputsconditionaloracleperturbations,notnativeA-onlycalibration. Scoredonfitdata,lowresidualdoesnotimplytrueprofile. Gridspan/curvature dependparameterization/endpoints. Same56correlatedfieldsandsamedataexplored,4capturemodelsnotindependentcalibration. Rankingassociationnotguarantee,abstentionthresholdorproductionguard.')
    with output.open('x',encoding='utf-8') as handle:json.dump(result,handle,ensure_ascii=False,indent=1,allow_nan=False)
    print('BASELINE',json.dumps(summaries['baseline']),flush=True);print('RESULT',output,flush=True)


if __name__=='__main__':run()
